+        repeated string args = 2;
+    }
+    message ResourceLimit {
+        // Num of required millicores
+        int32 cpu_limit = 2;
+        // Memory required, it can be expressed as 1000MB or 1GB
+        string memory_limit = 3;
+        // Disk IO required, it can be expressed as 1MB/s or 2MB/s.
+        // Read and Write will have separate limits
+        string disk_read_io_limit = 4;
+        string disk_write_io_limit = 5;
+    }
+    // Go doesn't provide the option to use pipe in single command. We need to rely on
+    // `os.pipe`, therfore the output from first command will feed to second command and
+    // continue with chaining. 
+    repeated ProcessCommand commands = 1;
+     
+    ResourceLimit limits = 2;
+}
+
+message JobStartResponse {
+    // JobID which can be used for status check
+    string job_id = 1;
+}
+
+message JobStatusRequest {
+    string job_id = 1;
+}
+
+// Will rely on error code from grpc for resource not found
+message JobStatusResponse {
+    enum Status {
+        RUN_INITIATED = 0;
+        RUNNING = 1;
+        FAILED = 2;
+        COMPLETED = 3;
+        STOP_INITIATED = 4;
+        STOPPED = 5;
+        
+    }
+
+    Status staus = 1;
+    // Useful for debugging in case of Failures.
+    string message = 2;
+    int32 start_time_ms = 3;
+    int32 duration_ms = 4;
+    // Identity of remote user who initiated the command.
+    string started_by = 5;
+}
+
+message JobStopRequest {
+    string job_id = 1;
+    bool force_stop = 2;
+}
+
+message JobStopResponse {
+    enum Status {
+        STOP_INITIATED = 0;
+        STOP_IN_PROGRESS = 1;
+    }
+    Status status = 1;
+}
+
+message JobStreamRequest {
+    string job_id = 1;
+}
+
+message JobStreamResponse {
+    enum Status {
+        IN_PROGRESS = 0;
+        COMPLETED = 1;
+    }
+    // To update if the process is completed and we have reached the EOF 
+    Status status = 1;
+    bytes stream = 2;
+}
+
+service HelloService {
+  rpc StartJob(JobStartRequest) returns (JobStartReponse);
+  rpc StopJob(JobStopRequest) returns (JobStopResponse);
+  rpc StatusJob(JobStatusRequest) returns (JobStatusResponse);
+  rpc StreamJobOutput(JobStreamRequest) return (stream JobStreamResponse);
+}
+
